d={"title":"Vulnerabilidades web: una introducción defensiva","fps":30,"width":1920,"height":1080,"duration":sum(s['duration'] for s in CHAPTERS),"sources":["https://top10.owasp.org/2025/","https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html","https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html"],"scenes":[]}
t=0
for i,s in enumerate(CHAPTERS):
    s.update(index=i,start=t)
    (R/"text").mkdir(exist_ok=True)
